// Backups on Proxmox Backup Server (PBS).
//
//   PBS server   connected by an owner (token secret sealed, TLS fingerprint pinned);
//                serves some clusters (or all) from one datastore.
//   Namespace    one per customer: panel/c<userId>. Backups of a customer never sit
//                next to another customer's, so a reused VMID can't expose them.
//   Storage      a Proxmox storage entry per customer and cluster (type pbs, with the
//                namespace), created when the customer's first backup runs there.
//   Encryption   optional, a key per customer: generated by Proxmox at the first
//                storage ("autogen"), kept sealed in the panel and reused on other
//                clusters. Without the key nobody can read the backups (export it).
//   Policy       when and how long (daily or weekly, keep N daily / weekly / monthly);
//                a plan points to one, a server may override it (an add-on with a
//                monthly price) or be excluded.
//
// Jobs, restores and the customer view build on this (see the routes).

import { db, audit } from './db.js';
import { seal, open } from './secrets.js';
import { rawRequest, dispatcherFor, allClusters, clusterById, pve } from './pve.js';
import { fingerprintOf } from './clusters.js';

const KEY = 'backup';
const PURPOSE = 'pbs-token';
const KEY_PURPOSE = 'pbs-encryption-key';
const fail = (status, message) => Object.assign(new Error(message), { statusCode: status, expose: true });

// ---- Settings ---------------------------------------------------------------------------

const DEFAULTS = {
  enabled: false,          // backups run and customers see them
  windowStart: 1,          // hours in the panel's time zone
  windowEnd: 5,
  parallelPerNode: 2,
  bwlimitMBs: 200,         // per job; 0 = no limit
  manualPerDay: 2,         // customer's own backups per server per day
  keepAfterDeleteDays: 30, // backups of a deleted server, then removed
  encrypt: true,           // a key per customer
  defaultPolicyId: null,   // servers without a plan (or a plan without a policy)
};

export function backupSettings() {
  const row = db.prepare('SELECT value FROM settings WHERE key = ?').get(KEY);
  return { ...DEFAULTS, ...(row ? JSON.parse(row.value) : {}) };
}

export function saveBackupSettings(input) {
  const s = backupSettings();
  const int = (k, min, max, label) => {
    if (input[k] === undefined) return;
    const n = Number(input[k]);
    if (!Number.isInteger(n) || n < min || n > max) throw fail(400, `${label}: ${min} to ${max}`);
    s[k] = n;
  };
  if (typeof input.enabled === 'boolean') s.enabled = input.enabled;
  if (typeof input.encrypt === 'boolean') s.encrypt = input.encrypt;
  int('windowStart', 0, 23, 'Window start hour');
  int('windowEnd', 0, 23, 'Window end hour');
  if (s.windowStart === s.windowEnd) throw fail(400, 'The backup window needs a start and an end hour that differ');
  int('parallelPerNode', 1, 16, 'Parallel jobs per node');
  int('bwlimitMBs', 0, 10_000, 'Bandwidth limit (MB/s, 0 = none)');
  int('manualPerDay', 0, 24, 'Manual backups per server per day');
  int('keepAfterDeleteDays', 0, 3650, 'Days to keep backups of deleted servers');
  if (input.defaultPolicyId !== undefined) {
    const id = input.defaultPolicyId === null ? null : Number(input.defaultPolicyId);
    if (id !== null && !db.prepare('SELECT 1 FROM backup_policies WHERE id = ?').get(id)) throw fail(400, 'Policy not found');
    s.defaultPolicyId = id;
  }
  if (s.enabled && !db.prepare('SELECT 1 FROM pbs_servers WHERE enabled = 1').get()) throw fail(409, 'Connect a Proxmox Backup Server first');
  db.prepare(`INSERT INTO settings (key, value, updated_at) VALUES (?, ?, datetime('now'))
    ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`).run(KEY, JSON.stringify(s));
  return s;
}

// ---- PBS servers -------------------------------------------------------------------------

const authOf = (tokenId, secret) => `PBSAPIToken=${tokenId}:${secret}`;
const pbsConn = (row, secret = null) => ({
  id: row.id ?? -1, name: row.name ?? 'pbs', main: false, url: String(row.url).replace(/\/+$/, ''),
  auth: authOf(row.token_id ?? row.tokenId, secret ?? open(PURPOSE, row.token_secret)),
  dispatcher: dispatcherFor({ url: row.url, verifyTls: !row.fingerprint, fingerprint: row.fingerprint ?? null }),
});
export const pbsApi = (row) => {
  const c = pbsConn(row);
  return { get: (p, q) => rawRequest(c, 'GET', p, q), post: (p, q) => rawRequest(c, 'POST', p, q), del: (p, q) => rawRequest(c, 'DELETE', p, q) };
};

function checkInput(input) {
  const name = String(input.name ?? '').trim().toLowerCase();
  if (!/^[a-z][a-z0-9-]{0,30}$/.test(name)) throw fail(400, 'Name: lowercase letters, digits and dashes, e.g. pbs-jkt');
  const url = String(input.url ?? '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\/[^\s/]+$/.test(url)) throw fail(400, 'Address: https://host:8007 (no path)');
  const tokenId = String(input.tokenId ?? '').trim();
  if (!/^[\w.-]+@[\w.-]+![\w.-]+$/.test(tokenId)) throw fail(400, 'API token ID: user@realm!tokenname');
  const fingerprint = input.fingerprint ? String(input.fingerprint).trim().toUpperCase() : null;
  if (fingerprint && !/^([0-9A-F]{2}:){31}[0-9A-F]{2}$/.test(fingerprint)) throw fail(400, 'Fingerprint: SHA-256, 32 hex pairs separated by colons');
  return { name, url, tokenId, fingerprint };
}

/** Connects and lists the datastores with their usage; nothing is changed. */
export async function testPbs(input, { existingId = null } = {}) {
  const { url, tokenId, fingerprint } = checkInput({ name: 'test', ...input });
  let secret = String(input.tokenSecret ?? '').trim();
  const old = existingId ? db.prepare('SELECT * FROM pbs_servers WHERE id = ?').get(existingId) : null;
  if (!secret && old) secret = open(PURPOSE, old.token_secret);
  if (!secret) throw fail(400, 'Enter the API token secret');
  const seen = await fingerprintOf(url);
  const c = pbsConn({ url, token_id: tokenId, fingerprint }, secret);
  try {
    const [version, usage] = await Promise.all([rawRequest(c, 'GET', '/version'), rawRequest(c, 'GET', '/status/datastore-usage')]);
    return {
      ok: true, version: version?.version ?? null, fingerprint: seen,
      datastores: (usage ?? []).map((d) => ({ name: d.store, total: d.total ?? null, used: d.used ?? null, avail: d.avail ?? null })),
    };
  } catch (err) {
    const tlsHint = url.startsWith('https:') && !fingerprint && seen ? ' If the server uses its own (self-signed) certificate, confirm its fingerprint below.' : '';
    return { ok: false, fingerprint: seen, error: `${err.statusCode === 401 ? 'The API token was refused (ID or secret wrong, or no rights)' : err.message}${err.statusCode === 401 ? '' : tlsHint}` };
  }
}

const pubPbs = (r) => ({
  id: r.id, name: r.name, url: r.url, tokenId: r.token_id, fingerprint: r.fingerprint, datastore: r.datastore,
  clusters: JSON.parse(r.clusters || '[]'), enabled: !!r.enabled, createdAt: r.created_at,
  storages: db.prepare('SELECT COUNT(*) AS n FROM pbs_storages WHERE pbs_id = ?').get(r.id).n,
});
export const listPbs = () => db.prepare('SELECT * FROM pbs_servers ORDER BY name').all().map(pubPbs);

function clustersInput(list) {
  const ids = [...new Set((list ?? []).map(Number))];
  const unknown = ids.filter((id) => !clusterById(id));
  if (unknown.length) throw fail(400, `Unknown cluster ${unknown.join(', ')}`);
  return ids;
}

export async function addPbs(req, input) {
  const { name, url, tokenId, fingerprint } = checkInput(input);
  if (db.prepare('SELECT 1 FROM pbs_servers WHERE name = ?').get(name)) throw fail(409, `A backup server ${name} exists already`);
  const datastore = String(input.datastore ?? '').trim();
  if (!/^[A-Za-z0-9_][A-Za-z0-9._-]{0,31}$/.test(datastore)) throw fail(400, 'Choose the datastore');
  const clusters = clustersInput(input.clusters);
  const t = await testPbs({ url, tokenId, tokenSecret: input.tokenSecret, fingerprint });
  if (!t.ok) throw fail(409, t.error);
  if (!t.datastores.some((d) => d.name === datastore)) throw fail(409, `The datastore ${datastore} was not found on this server`);
  const id = Number(db.prepare(`INSERT INTO pbs_servers (name, url, token_id, token_secret, fingerprint, datastore, clusters)
    VALUES (?, ?, ?, ?, ?, ?, ?)`).run(name, url, tokenId, seal(PURPOSE, String(input.tokenSecret).trim()), fingerprint, datastore, JSON.stringify(clusters)).lastInsertRowid);
  audit(req, null, 'admin_pbs_added', { id, name, url, datastore, clusters });
  return pubPbs(db.prepare('SELECT * FROM pbs_servers WHERE id = ?').get(id));
}

export function updatePbs(req, id, input) {
  const r = db.prepare('SELECT * FROM pbs_servers WHERE id = ?').get(id);
  if (!r) throw fail(404, 'Backup server not found');
  const clusters = input.clusters !== undefined ? clustersInput(input.clusters) : JSON.parse(r.clusters || '[]');
  const enabled = typeof input.enabled === 'boolean' ? input.enabled : !!r.enabled;
  db.prepare('UPDATE pbs_servers SET clusters = ?, enabled = ? WHERE id = ?').run(JSON.stringify(clusters), enabled ? 1 : 0, id);
  if (input.tokenSecret) db.prepare('UPDATE pbs_servers SET token_secret = ? WHERE id = ?').run(seal(PURPOSE, String(input.tokenSecret).trim()), id);
  audit(req, null, 'admin_pbs_updated', { id, name: r.name, clusters, enabled, secretChanged: !!input.tokenSecret });
  return pubPbs(db.prepare('SELECT * FROM pbs_servers WHERE id = ?').get(id));
}

/** Removes the connection and the Proxmox storage entries; the backups stay on the PBS. */
export async function removePbs(req, id) {
  const r = db.prepare('SELECT * FROM pbs_servers WHERE id = ?').get(id);
  if (!r) throw fail(404, 'Backup server not found');
  for (const s of db.prepare('SELECT * FROM pbs_storages WHERE pbs_id = ?').all(id)) {
    await pve.on(s.cluster_id).del(`/storage/${encodeURIComponent(s.storage)}`).catch(() => {});
  }
  db.prepare('DELETE FROM pbs_servers WHERE id = ?').run(id);
  audit(req, null, 'admin_pbs_removed', { id, name: r.name });
  return { removed: true };
}

/** Datastore figures of a backup server: size, use, dedup (from the last GC), last verify. */
export async function pbsStatus(row) {
  const api = pbsApi(row);
  const store = encodeURIComponent(row.datastore);
  try {
    const [st, tasks] = await Promise.all([
      api.get(`/admin/datastore/${store}/status`),
      api.get('/nodes/localhost/tasks', { typefilter: 'verif', store: row.datastore, limit: 1 }).catch(() => []),
    ]);
    const gc = st?.['gc-status'] ?? {};
    const v = (tasks ?? [])[0];
    return {
      reachable: true, total: st?.total ?? null, used: st?.used ?? null, avail: st?.avail ?? null,
      dedup: gc['disk-bytes'] ? Math.round((gc['index-data-bytes'] / gc['disk-bytes']) * 10) / 10 : null,
      lastGc: gc.upid ? { ok: !gc['removed-bad'], at: gc['last-run-endtime'] ? new Date(gc['last-run-endtime'] * 1000).toISOString() : null } : null,
      lastVerify: v ? { ok: v.status === 'OK', status: v.status ?? null, at: v.endtime ? new Date(v.endtime * 1000).toISOString() : null } : null,
    };
  } catch (err) {
    return { reachable: false, error: err.statusCode === 401 ? 'The API token was refused' : err.message };
  }
}

/** The backup server for a cluster: the first enabled one that serves it. */
export function pbsForCluster(clusterId) {
  return db.prepare('SELECT * FROM pbs_servers WHERE enabled = 1 ORDER BY id').all()
    .find((r) => { const c = JSON.parse(r.clusters || '[]'); return !c.length || c.includes(Number(clusterId)); }) ?? null;
}

// ---- Customer namespaces and storages ---------------------------------------------------

export const namespaceOf = (userId) => `panel/c${userId}`;
const storageIdOf = (pbsId, userId) => `pbs${pbsId}-c${userId}`;

/**
 * The Proxmox storage for a customer's backups on a cluster: created on first use
 * (namespace on the PBS, storage entry on the cluster, encryption key on the first one).
 */
export async function storageFor(userId, clusterId) {
  const pbs = pbsForCluster(clusterId);
  if (!pbs) throw fail(409, 'No backup server serves this cluster');
  const known = db.prepare('SELECT storage FROM pbs_storages WHERE pbs_id = ? AND user_id = ? AND cluster_id = ?').get(pbs.id, userId, clusterId);
  if (known) return { storage: known.storage, pbs };

  // namespace panel/c<id> (and panel itself) on the datastore; existing ones are fine
  const api = pbsApi(pbs);
  const ns = `/admin/datastore/${encodeURIComponent(pbs.datastore)}/namespace`;
  await api.post(ns, { name: 'panel' }).catch((err) => { if (!/exist/i.test(err.message)) throw err; });
  await api.post(ns, { name: `c${userId}`, parent: 'panel' }).catch((err) => { if (!/exist/i.test(err.message)) throw err; });

  const u = new URL(pbs.url);
  const storage = storageIdOf(pbs.id, userId);
  const keyRow = db.prepare('SELECT key_sealed FROM backup_keys WHERE user_id = ?').get(userId);
  const encrypt = backupSettings().encrypt;
  const params = {
    storage, type: 'pbs', server: u.hostname, port: u.port || 8007, datastore: pbs.datastore, namespace: namespaceOf(userId),
    username: pbs.token_id, password: open(PURPOSE, pbs.token_secret), fingerprint: pbs.fingerprint ?? undefined, content: 'backup',
    ...(encrypt ? { 'encryption-key': keyRow ? open(KEY_PURPOSE, keyRow.key_sealed) : 'autogen' } : {}),
  };
  const res = await pve.on(clusterId).post('/storage', params).catch(async (err) => {
    if (!/already (exists|defined)/i.test(err.message)) throw err;
    return null;                                      // left over from an earlier attempt: reuse it
  });
  const generated = res?.config?.['encryption-key'];
  if (encrypt && !keyRow && generated) {
    db.prepare('INSERT INTO backup_keys (user_id, key_sealed) VALUES (?, ?) ON CONFLICT(user_id) DO NOTHING').run(userId, seal(KEY_PURPOSE, String(generated)));
  }
  db.prepare('INSERT INTO pbs_storages (pbs_id, user_id, cluster_id, storage) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING').run(pbs.id, userId, clusterId, storage);
  audit({ account: { id: userId }, ip: 'backup' }, null, 'backup_storage_created', { pbs: pbs.name, cluster: clusterById(clusterId)?.name ?? clusterId, storage, encrypted: !!encrypt });
  return { storage, pbs };
}

/** Owner: the customer's encryption key, to keep somewhere safe (audited). */
export function exportKey(req, userId) {
  const row = db.prepare('SELECT key_sealed, created_at FROM backup_keys WHERE user_id = ?').get(userId);
  if (!row) throw fail(404, 'This customer has no encryption key yet (it is made with their first backup)');
  audit(req, null, 'admin_backup_key_exported', { userId });
  return { userId, createdAt: row.created_at, key: open(KEY_PURPOSE, row.key_sealed) };
}

// ---- Policies ------------------------------------------------------------------------------

const pubPolicy = (p) => ({
  id: p.id, name: p.name, frequency: p.frequency, weekday: p.weekday, keepDaily: p.keep_daily, keepWeekly: p.keep_weekly,
  keepMonthly: p.keep_monthly, addonPrice: p.addon_price,
  plans: db.prepare('SELECT id, name FROM plans WHERE backup_policy_id = ? ORDER BY sort, name').all(p.id),
  servers: serversOfPolicy(p.id),
});

/** Servers this policy applies to now (plan, override or panel default). */
function serversOfPolicy(policyId) {
  const def = backupSettings().defaultPolicyId;
  return db.prepare(`SELECT COUNT(*) AS n FROM vms v LEFT JOIN plans p ON p.id = v.plan_id
    WHERE v.backup_excluded = 0 AND COALESCE(v.backup_policy_id, p.backup_policy_id, ?) = ?`).get(def, policyId).n;
}

export const listPolicies = () => db.prepare('SELECT * FROM backup_policies ORDER BY name').all().map(pubPolicy);

function policyInput(input, cur = null) {
  const name = String(input.name ?? cur?.name ?? '').trim();
  if (!name || name.length > 60) throw fail(400, 'Name: up to 60 characters');
  const frequency = input.frequency ?? cur?.frequency;
  if (!['daily', 'weekly'].includes(frequency)) throw fail(400, 'Frequency: daily or weekly');
  const weekday = frequency === 'weekly' ? Number(input.weekday ?? cur?.weekday) : null;
  if (frequency === 'weekly' && !(Number.isInteger(weekday) && weekday >= 0 && weekday <= 6)) throw fail(400, 'Day of the week: 0 (Sunday) to 6');
  const keep = (k, col) => {
    const n = Number(input[k] ?? cur?.[col] ?? 0);
    if (!Number.isInteger(n) || n < 0 || n > 400) throw fail(400, 'Retention: 0 to 400');
    return n;
  };
  const keepDaily = keep('keepDaily', 'keep_daily');
  const keepWeekly = keep('keepWeekly', 'keep_weekly');
  const keepMonthly = keep('keepMonthly', 'keep_monthly');
  if (!keepDaily && !keepWeekly && !keepMonthly) throw fail(400, 'Keep at least one backup (daily, weekly or monthly)');
  if (frequency === 'weekly' && keepDaily) throw fail(400, 'A weekly policy keeps weekly or monthly backups, not daily ones');
  const price = input.addonPrice === undefined ? cur?.addon_price ?? null : input.addonPrice;
  if (price !== null && !(Number.isInteger(Number(price)) && Number(price) >= 0 && Number(price) <= 100_000_000)) throw fail(400, 'Add-on price: whole rupiah, or empty');
  return { name, frequency, weekday, keepDaily, keepWeekly, keepMonthly, addonPrice: price === null ? null : Number(price) };
}

export function createPolicy(req, input) {
  const p = policyInput(input);
  if (db.prepare('SELECT 1 FROM backup_policies WHERE name = ?').get(p.name)) throw fail(409, `A policy ${p.name} exists already`);
  const id = Number(db.prepare(`INSERT INTO backup_policies (name, frequency, weekday, keep_daily, keep_weekly, keep_monthly, addon_price)
    VALUES (?, ?, ?, ?, ?, ?, ?)`).run(p.name, p.frequency, p.weekday, p.keepDaily, p.keepWeekly, p.keepMonthly, p.addonPrice).lastInsertRowid);
  audit(req, null, 'admin_backup_policy_created', { id, ...p });
  return pubPolicy(db.prepare('SELECT * FROM backup_policies WHERE id = ?').get(id));
}

export function updatePolicy(req, id, input) {
  const cur = db.prepare('SELECT * FROM backup_policies WHERE id = ?').get(id);
  if (!cur) throw fail(404, 'Policy not found');
  const p = policyInput(input, cur);
  if (p.name !== cur.name && db.prepare('SELECT 1 FROM backup_policies WHERE name = ?').get(p.name)) throw fail(409, `A policy ${p.name} exists already`);
  db.prepare(`UPDATE backup_policies SET name = ?, frequency = ?, weekday = ?, keep_daily = ?, keep_weekly = ?, keep_monthly = ?, addon_price = ? WHERE id = ?`)
    .run(p.name, p.frequency, p.weekday, p.keepDaily, p.keepWeekly, p.keepMonthly, p.addonPrice, id);
  audit(req, null, 'admin_backup_policy_updated', { id, ...p });
  return pubPolicy(db.prepare('SELECT * FROM backup_policies WHERE id = ?').get(id));
}

export function deletePolicy(req, id) {
  const cur = db.prepare('SELECT * FROM backup_policies WHERE id = ?').get(id);
  if (!cur) throw fail(404, 'Policy not found');
  const plans = db.prepare('SELECT COUNT(*) AS n FROM plans WHERE backup_policy_id = ?').get(id).n;
  const addons = db.prepare('SELECT COUNT(*) AS n FROM vms WHERE backup_policy_id = ?').get(id).n;
  if (plans || addons) throw fail(409, `Used by ${plans} plan(s) and ${addons} server(s); move them to another policy first`);
  if (backupSettings().defaultPolicyId === id) throw fail(409, 'This is the default policy; choose another default first');
  db.prepare('DELETE FROM backup_policies WHERE id = ?').run(id);
  audit(req, null, 'admin_backup_policy_deleted', { id, name: cur.name });
  return { deleted: true };
}

/** Which policy a plan uses (null: none). */
export function setPlanPolicy(req, planId, policyId) {
  if (!db.prepare('SELECT 1 FROM plans WHERE id = ?').get(planId)) throw fail(404, 'Plan not found');
  if (policyId !== null && !db.prepare('SELECT 1 FROM backup_policies WHERE id = ?').get(policyId)) throw fail(400, 'Policy not found');
  db.prepare('UPDATE plans SET backup_policy_id = ? WHERE id = ?').run(policyId, planId);
  audit(req, null, 'admin_plan_backup_policy', { planId, policyId });
  return { planId, policyId };
}

/** The policy that applies to a server row now, or null (none, or excluded). */
export function policyOfServer(row) {
  if (!row || row.backup_excluded) return null;
  const id = row.backup_policy_id
    ?? db.prepare('SELECT backup_policy_id FROM plans WHERE id = ?').get(row.plan_id ?? -1)?.backup_policy_id
    ?? backupSettings().defaultPolicyId;
  return id ? db.prepare('SELECT * FROM backup_policies WHERE id = ?').get(id) ?? null : null;
}

/** Monthly price of a server's backup add-on (renewals), or null. */
export function addonOf(vmid) {
  const r = db.prepare(`SELECT p.name, p.addon_price FROM vms v JOIN backup_policies p ON p.id = v.backup_policy_id
    WHERE v.vmid = ? AND v.backup_excluded = 0 AND p.addon_price IS NOT NULL`).get(vmid);
  return r && r.addon_price > 0 ? { name: r.name, monthly: r.addon_price } : null;
}

/** "keep-daily=7,keep-weekly=4" for Proxmox. */
export const pruneOf = (p) => [['keep-daily', p.keep_daily], ['keep-weekly', p.keep_weekly], ['keep-monthly', p.keep_monthly]]
  .filter(([, n]) => n > 0).map(([k, n]) => `${k}=${n}`).join(',');

/** Admin overview of the configuration (stage 1): servers, policies, settings, clusters. */
export async function backupOverview() {
  const rows = db.prepare('SELECT * FROM pbs_servers ORDER BY name').all();
  const status = await Promise.all(rows.map((r) => (r.enabled ? pbsStatus(r) : Promise.resolve(null))));
  return { ...backupConfig(), servers: rows.map((r, i) => ({ ...pubPbs(r), status: status[i] })) };
}

export function backupConfig() {
  return {
    settings: backupSettings(), servers: listPbs(), policies: listPolicies(),
    plans: db.prepare('SELECT id, name, backup_policy_id AS policyId, active FROM plans ORDER BY sort, name').all().map((p) => ({ ...p, active: !!p.active })),
    clusters: allClusters().map((c) => ({ id: c.id, name: c.name })),
    keys: db.prepare('SELECT COUNT(*) AS n FROM backup_keys').get().n,
  };
}
